Method.Implementation:
set stat = $$$OK
set pResponse=##class(Ens.StringContainer).%New()
set pResponse.StringValue="SUCCESS"
$$$TRACE("Inside OnMessage ..")
try
{
	if ( ($IsObject(..JavaGateway)) && ($IsObject(..ActMqObj)))
	{
		set x12Str = pRequest.RawContent
		If ($L(x12Str) > 0)
		{
			$$$TRACE("EnsLib.EDI.X12.Document RawContent: length: " _ $L(x12Str) _ ", X12: " _ x12Str)
			// Do ##class(org.ihc.itf.activemq.IhcActiveMQUtils).SendMessageToActiveMQ(..JavaGateway,..MQUrl,..QueueName,x12Str)
			Do ..ActMqObj.sendMsg(x12Str)
			$$$TRACE("Message Sent")
			set pResponse.StringValue="SUCCESS"
		}else {
			set stat=$$$ERROR($$$GeneralError,"Data "_ x12Str _" Not valid")
			set pResponse.StringValue="FAILURE"
		}
	}
	ELSE
	{
		set stat=$$$ERROR($$$GeneralError,"JavaGateway or ActMqObj are Not valid")
	}


}catch errobj {
	set ..ActMqObj = $$$NULLOREF
    $$$LOGERROR("Error in OnMessage: "  _ errobj.AsSystemError() _ " _ data: " _ errobj.Data _ "; code:" _ errobj.Code)
    set pResponse.StringValue="FAILURE"
    set stat = $$$ERROR("Error in OnMessage " _ errobj.AsSystemError() _ " _ data: " _ errobj.Data _ "; code:" _ errobj.Code)
}
return stat

	Set tStat = $$$OK


	 SET localhost=$SYSTEM.INetInfo.LocalHostName()            /* get host name */
     $$$TRACE($NAMESPACE _", local host name is " _ localhost)

	// get an instance of JavaGateway and connect to JavaGateway Super Server
	try {

		if ($L(..JMSJarPath) = 0)
		{
		   	$$$TRACE("JMSJarPath does not have class path for the jar files ")
		}
		else
		{

			Set listArray = ##class(%ListOfDataTypes).%New()
			Set p=1
			For {
				Set piece=$P(..JMSJarPath,":",p)
				Quit:piece=""
				do listArray.Insert(piece)
				set p = p+1
				Do ..JavaGateway.%Import(piece)
				$$$TRACE("Import Jar file: " _ piece)
			}

		}
		$$$TRACE("Imported Jar, creating ActiveMQClass to connect to " _ ..JmsUrl _ ", Queue: " _ ..QueueName  )
		set ..ActMqObj = ##class(IHC.ITF.ITFCOMMON.JMS.ActiveMQ.ActiveMQClass).%New(..JavaGateway, ..JmsUrl, ..QueueName, ..LogDirectory _ "/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName) )

		$$$TRACE("Created class IHC.ITF.ITFCOMMON.JMS.ActiveMQ.ActiveMQClass: " _ ..JmsUrl _ ", " _ ..QueueName)
		$$$TRACE("JavaGateway: " _ $IsObject(..JavaGateway) _ ", ActMqObj:" _$IsObject(..ActMqObj))

		Do ..ActMqObj.CreateProducer()
		$$$TRACE("Created Producer")

	} catch err
     {
	     $$$TRACE("In exception")
	     if $GET(%objlasterror) '= ""
	    {
	        set errMsg =  $System.Status.GetErrorText(%objlasterror)
	    }
	    else
	    {
		    set errMsg = "No objlasterror"
	    }
   	    Set tStat=$$$ERROR($$$GeneralError, "OnInit : " _ err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " " _ errMsg)
     }
     return tStat
